SET NOCOUNT ON;SET XACT_ABORT ON;EXEC fwk.USP_WaitForSignal '$(DemoId)','$(RunToken)','WAITER_STARTED',15000;DECLARE @W smallint=(SELECT SessionId FROM fwk.SessionSignal WITH(READUNCOMMITTED) WHERE SignalName='WAITER_STARTED'),@B smallint=(SELECT SessionId FROM fwk.SessionSignal WITH(READUNCOMMITTED) WHERE SignalName='BLOCKER_LOCKED'),@Start datetime2(3)=SYSUTCDATETIME(),@TW nvarchar(60),@RW nvarchar(60),@Dur bigint;WHILE @TW IS NULL BEGIN SELECT TOP(1) @TW=wait_type,@Dur=wait_duration_ms FROM sys.dm_os_waiting_tasks WHERE session_id=@W AND blocking_session_id=@B;SELECT @RW=wait_type FROM sys.dm_exec_requests WHERE session_id=@W AND blocking_session_id=@B;IF DATEDIFF_BIG(millisecond,@Start,SYSUTCDATETIME())>15000 THROW 51005,'FAIL_TIMEOUT: RES-007-Wait wurde nicht sichtbar.',1;WAITFOR DELAY '00:00:00.050';END;UPDATE lab.Evidence SET WaiterSessionId=@W,BlockerSessionId=@B,TaskWaitType=@TW,RequestWaitType=@RW,WaitDurationMs=@Dur WHERE EvidenceId=1;EXEC fwk.USP_Signal '$(DemoId)','$(RunToken)','OBSERVED';PRINT 'SQLPERF_SUMMARY|PASS|OK';
